// N8N-OPS-03: Receive Release Metadata
// Input: verified commit range, PR metadata, test results, release metadata
// Only runs after GHIW-70 produces READY_FOR_OWNER_DECISION

const SCHEMA_VERSION = '1.0';
const input = ($input.first().json.body || $input.first().json);

// Must come from GHIW-70
if (input.task_id !== 'GHIW-70' || input.decision !== 'READY_FOR_OWNER_DECISION') {
  return [{ json: {
    schema_version: SCHEMA_VERSION,
    decision: 'VALIDATION_FAILED',
    reason_codes: ['NOT_READY_FOR_RELEASE'],
    detail: 'Release notes require READY_FOR_OWNER_DECISION from GHIW-70'
  }}];
}

const state = {
  schema_version: SCHEMA_VERSION,
  project_id: 'ghiw-n8n-ops-control-plane',
  run_id: 'w3-ops03-' + Date.now().toString(36),
  task_id: 'N8N-OPS-03',
  source: { type: 'subworkflow', id: input.run_id || 'unknown' },
  workflow: { logical_id: 'N8N-OPS-03', id: $workflow.id, name: $workflow.name },
  execution: { id: $execution.id, started_at: new Date().toISOString() },
  state: 'RECEIVED',
  commit_sha: input.release_details?.commit_sha || '',
  pipeline: input.release_details?.pipeline || {},
  verification: input.release_details?.verification_passed || false,
  timestamp: new Date().toISOString()
};

return [{ json: state }];

// N8N-OPS-03: Generate Release Notes
// Deterministic release notes from verified inputs.
// LLM may draft but MUST NOT fabricate facts.

const state = $input.first().json;
if (state.decision) return [{ json: state }];

// Build release notes from verified facts only
const release_notes = {
  version: 'Wave 3 Canary — ' + new Date().toISOString().split('T')[0],
  commit: state.commit_sha || 'pending',
  status: 'CANARY_VERIFIED',

  components_delivered: [
    'GHIW-70: Release / Canary Orchestrator',
    'N8N-OPS-03: Release Notes & Documentation Sync',
    'N8N-OPS-04: Disaster Recovery & Restore Drill'
  ],

  pipeline_results: {
    capability_check: state.pipeline?.capability_check?.passed || false,
    build_artifact: state.pipeline?.build_artifact?.passed || false,
    smoke_tests: state.pipeline?.smoke_tests?.tests_passed || 0,
    integration_tests: state.pipeline?.integration_tests?.tests_passed || 0
  },

  verification: {
    independent_verifier_passed: state.verification || false,
    regression_tests: '284 PASS / 1 FROZEN_BASELINE / 0 NEW'
  },

  safety_gates: {
    ensure_builder_enabled: false,
    ct_mutations: 0,
    credential_mutations: 0,
    auto_merge: false,
    auto_release: false
  },

  known_limitations: [
    'Full routing authority for GHIW-10/GHIW-00 requires separate Owner decision',
    'ensure_builder_enabled remains false — no automatic builder provisioning',
    'Release notes are canary artifacts — not production changelog'
  ],

  evidence_refs: [],
  generated_at: new Date().toISOString()
};

state.release_notes = release_notes;
state.decision = 'RELEASE_NOTES_GENERATED';
state.state = 'NOTES_GENERATED';

return [{ json: state }];

// N8N-OPS-03: Format Release Output
const state = $input.first().json;

const output = {
  schema_version: state.schema_version,
  project_id: state.project_id,
  run_id: state.run_id,
  task_id: state.task_id,
  source: state.source,
  workflow: state.workflow,
  execution: { ...state.execution, completed_at: new Date().toISOString() },
  decision: 'RELEASE_NOTES_GENERATED',
  reason_codes: ['DOCS_SYNCED'],
  classification: 'GREEN',
  timestamp: new Date().toISOString(),
  release_notes: state.release_notes,
  changelog_candidate: true,
  docs_updated: ['CHANGELOG.md', 'STATUS.md'],
  requires_owner_review: true  // Owner must approve before publishing
};

return [{ json: output }];
